from collections import deque

# DFS: path / subtree answers. BFS: level-by-level / shortest depth.
def min_depth(root):  # BFS stops at the first leaf
    if not root:
        return 0
    q = deque([(root, 1)])
    while q:
        t, d = q.popleft()
        if not t.left and not t.right:
            return d
        if t.left: q.append((t.left, d + 1))
        if t.right: q.append((t.right, d + 1))
