// O(n) time; O(h) recursion stack (h = n when skewed).
// Pitfall: handle null first; balanced check in one pass returns -1.
int heightOrMinus1(TreeNode t) {
    if (t == null) return 0;
    int l = heightOrMinus1(t.left), r = heightOrMinus1(t.right);
    if (l < 0 || r < 0 || Math.abs(l - r) > 1) return -1;
    return 1 + Math.max(l, r);
}
```

