class Trie {
    private final Trie[] next = new Trie[26];
    private boolean end;

    void insert(String w) {
        Trie t = this;
        for (char c : w.toCharArray()) {
            if (t.next[c - 'a'] == null) t.next[c - 'a'] = new Trie();
            t = t.next[c - 'a'];
        }
        t.end = true;
    }

    boolean search(String w, boolean prefixOnly) {
        Trie t = this;
        for (char c : w.toCharArray()) {
            t = t.next[c - 'a'];
            if (t == null) return false;
        }
        return prefixOnly || t.end;
    }
}
