        t = self
        for c in w:
            t = t.next.setdefault(c, Trie())
        t.end = True

    def search(self, w, prefix_only=False):
        t = self
        for c in w:
            t = t.next.get(c)
            if t is None:
                return False
        return prefix_only or t.end
