    pq = [-s for s in stones]  # negate for a max-heap
    heapq.heapify(pq)
    while len(pq) > 1:
        a, b = -heapq.heappop(pq), -heapq.heappop(pq)
        if a != b:
            heapq.heappush(pq, -(a - b))
    return -pq[0] if pq else 0
