def merge_k_lists(lists):
    pq = [(n.val, i, n) for i, n in enumerate(lists) if n]  # i breaks ties
    heapq.heapify(pq)
    dummy = tail = ListNode(0)
    while pq:
        _, i, n = heapq.heappop(pq)
        tail.next = tail = n
        if n.next:
            heapq.heappush(pq, (n.next.val, i, n.next))
    return dummy.next
