void subsetsWithDup(int[] a, int start, List<Integer> path, List<List<Integer>> res) {
    res.add(new ArrayList<>(path)); // copy, not path itself
    for (int i = start; i < a.length; i++) {
        if (i > start && a[i] == a[i - 1]) continue; // a sorted
        path.add(a[i]);
        subsetsWithDup(a, i + 1, path, res);
        path.remove(path.size() - 1);
