def combination_sum(c, target):
    res, path = [], []
    def go(i, left):
        if left == 0:
            res.append(path[:])
            return
        if left < 0 or i == len(c):
            return
        path.append(c[i])
        go(i, left - c[i])  # reuse c[i]
        path.pop()
        go(i + 1, left)     # move past c[i]
    go(0, target)
    return res
```

