// BFS/DFS O(V + E). Pitfall: mark visited when ENQUEUING,
// otherwise a node can be queued many times.
void bfs(List<List<Integer>> adj, int s, boolean[] seen) {
    Deque<Integer> q = new ArrayDeque<>();
    q.offer(s); seen[s] = true;
    while (!q.isEmpty()) {
        int u = q.poll();
        for (int v : adj.get(u))
            if (!seen[v]) { seen[v] = true; q.offer(v); } // mark on push
    }
}
