from collections import deque

def oranges_rotting(g):
    R, C = len(g), len(g[0])
    q = deque((r, c) for r in range(R) for c in range(C) if g[r][c] == 2)
    fresh = sum(row.count(1) for row in g)
    mins = 0
    while q and fresh:  # multi-source BFS by level
        mins += 1
        for _ in range(len(q)):
            r, c = q.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == 1:
                    g[nr][nc] = 2
                    fresh -= 1
                    q.append((nr, nc))
    return mins if fresh == 0 else -1
```

- Weighted shortest path, **non-negative** weights → **Dijkstra**
- Shortest path with ≤ k edges / negative weights → **Bellman-Ford**
- Connect all points at min cost → **MST** (Prim or Kruskal + Union-Find)
- Use every edge once (itinerary) → **Hierholzer / Eulerian path**
- Dynamic connectivity, merging groups → **Union-Find**

**Java**

```java
// Weighted shortest path -> Dijkstra; connectivity -> Union-Find;
// MST -> Kruskal (sort edges + DSU) or Prim.
int kruskal(int n, int[][] edges) { // edge = {u, v, w}
    Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
    int[] p = new int[n];
    for (int i = 0; i < n; i++) p[i] = i;
    int total = 0;
    for (int[] e : edges) {
        int a = find(p, e[0]), b = find(p, e[1]);
        if (a != b) { p[a] = b; total += e[2]; }
    }
    return total;
}

int find(int[] p, int x) { return p[x] == x ? x : (p[x] = find(p, p[x])); }
```

