# Weighted shortest path -> Dijkstra; connectivity -> Union-Find;
# MST -> Kruskal (sort edges + DSU) or Prim.
def kruskal(n, edges):  # edge = (u, v, w)
    p = list(range(n))
    def find(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    total = 0
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        a, b = find(u), find(v)
        if a != b:
            p[a] = b
            total += w
    return total
```

