# Pitfall: skip stale heap entries (d > dist[u]).
def bellman_ford(n, edges, src):  # edge = (u, v, w)
    dist = [float("inf")] * n
    dist[src] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return dist
