// Pitfall: wrong base case / off-by-one in dp size (use n + 1).
int tribonacci(int n) {
    int[] dp = new int[Math.max(3, n + 1)]; // size n + 1
    dp[1] = dp[2] = 1;
    for (int i = 3; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3];
    return dp[n];
}
