// O(m * n) time; compress to one row when dp[i] only needs dp[i-1].
int uniquePathsOneRow(int m, int n) {
    int[] row = new int[n];
    Arrays.fill(row, 1);
    for (int i = 1; i < m; i++)
        for (int j = 1; j < n; j++)
            row[j] += row[j - 1]; // row[j] (old) = up, row[j-1] = left
    return row[n - 1];
}
