def single_number(nums):
    x = 0
    for v in nums:
        x ^= v  # pairs cancel
    return x

def popcount(n):
    c = 0
    while n:
        n &= n - 1  # clear lowest set bit
        c += 1
    return c

def is_power_of_two(n):
    return n > 0 and n & (n - 1) == 0

def count_bits(n):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i >> 1] + (i & 1)
    return dp
